{
  "status": "SUPPORTED",
  "task_summary": "A physical task requiring retrieval of a fastening tool and fastener components from the environment to secure a workpiece at a designated location, followed by tool return.",
  "task_contract": {
    "functional_roles": [
      {
        "id": "Fastening_Tool",
        "entity_kind": "OBJECT",
        "function": "Mechanical instrument for driving fasteners",
        "required_count": 1,
        "binding_policy": "REUSABLE",
        "candidate_categories": [
          "screwdriver",
          "power driver",
          "hand wrench",
          "manual tool"
        ],
        "required_properties": []
      },
      {
        "id": "Fastener_Component",
        "entity_kind": "OBJECT",
        "function": "Physical connector joining components",
        "required_count": 1,
        "binding_policy": "DISTINCT",
        "candidate_categories": [
          "screw",
          "bolt",
          "nut",
          "rivet",
          "anchor pin"
        ],
        "required_properties": [
          "threaded surface present",
          "machined head geometry"
        ]
      },
      {
        "id": "Target_Workpiece",
        "entity_kind": "OBJECT",
        "function": "Object receiving the fastening operation",
        "required_count": 1,
        "binding_policy": "SHARED",
        "candidate_categories": [
          "assembly bracket",
          "fixture plate",
          "machine housing",
          "structural component"
        ],
        "required_properties": []
      },
      {
        "id": "Storage_Zone",
        "entity_kind": "REGION",
        "function": "Container for locating required parts",
        "required_count": 1,
        "binding_policy": "SHARED",
        "candidate_categories": [
          "tool cabinet",
          "parts tray",
          "storage drawer",
          "open rack"
        ],
        "required_properties": [
          "enclosed or defined boundaries",
          "accessible to manipulator"
        ]
      },
      {
        "id": "Workbench_Surface",
        "entity_kind": "REGION",
        "function": "Designated location for tool deposition",
        "required_count": 1,
        "binding_policy": "SHARED",
        "candidate_categories": [
          "wooden table top",
          "metal workbench",
          "flat support surface"
        ],
        "required_properties": [
          "stable horizontal plane",
          "horizontal alignment"
        ]
      }
    ],
    "functional_relations": [
      {
        "id": "relation_1",
        "subject_role": "Fastening_Tool",
        "relation": "physically acts upon",
        "object_role": "Target_Workpiece",
        "required": true
      },
      {
        "id": "relation_2",
        "subject_role": "Fastener_Component",
        "relation": "mechanically attaches_to",
        "object_role": "Target_Workpiece",
        "required": true
      },
      {
        "id": "relation_3",
        "subject_role": "Fastener_Component",
        "relation": "originally contained_in",
        "object_role": "Storage_Zone",
        "required": true
      },
      {
        "id": "relation_4",
        "subject_role": "Fastening_Tool",
        "relation": "rests_on",
        "object_role": "Workbench_Surface",
        "required": true
      },
      {
        "id": "relation_5",
        "subject_role": "Fastening_Tool",
        "relation": "transferred_from",
        "object_role": "Storage_Zone",
        "required": true
      }
    ],
    "operation_pairings": [
      {
        "id": "op_1",
        "operation": "Retrieve Fastening Tool from Storage",
        "source_role": "Fastening_Tool",
        "target_role": "Target_Workpiece",
        "operation_count": 1,
        "reuse_policy": "DEDICATED_PER_TARGET",
        "anchor_role": "Storage_Zone"
      },
      {
        "id": "op_2",
        "operation": "Retrieve Fastener from Storage",
        "source_role": "Fastener_Component",
        "target_role": "Target_Workpiece",
        "operation_count": 1,
        "reuse_policy": "DEDICATED_PER_TARGET",
        "anchor_role": "Storage_Zone"
      },
      {
        "id": "op_3",
        "operation": "Secure Fastener to Workpiece",
        "source_role": "Fastening_Tool",
        "target_role": "Target_Workpiece",
        "operation_count": 1,
        "reuse_policy": "REUSABLE_ACROSS_TARGETS",
        "anchor_role": "Target_Workpiece"
      },
      {
        "id": "op_4",
        "operation": "Return Fastening Tool to Workbench",
        "source_role": "Fastening_Tool",
        "target_role": "Workbench_Surface",
        "operation_count": 1,
        "reuse_policy": "REUSABLE_ACROSS_TARGETS",
        "anchor_role": "Workbench_Surface"
      }
    ]
  },
